"""OpenVPN configuration generator."""

import logging
from pathlib import Path

from vpn_portal.config import settings

logger = logging.getLogger(__name__)

# OpenVPN client configuration template
OVPN_TEMPLATE = """\
# OpenVPN Zero-Trust Client Configuration
# Generated by VPN Portal
# Valid until: {expires_at}

client
dev tun
proto {proto}
remote {server} {port}
resolv-retry infinite
nobind
persist-key
persist-tun

# Security
remote-cert-tls server
cipher AES-256-GCM
auth SHA256
verb 3

# DNS
script-security 2
dhcp-option DNS 10.8.0.1

# Certificate and Key (inline)
<ca>
{ca_certificate}
</ca>

<cert>
{certificate}
</cert>

<key>
{private_key}
</key>

<tls-auth>
{ta_key}
</tls-auth>
key-direction 1
"""


class OVPNGeneratorError(Exception):
    """OpenVPN configuration generation error."""

    pass


def load_ta_key() -> str:
    """Load TLS auth key from file.

    Returns:
        TLS auth key content.

    Raises:
        OVPNGeneratorError: If file cannot be read.
    """
    ta_path = Path(settings.openvpn_ta_key_path)
    if not ta_path.exists():
        raise OVPNGeneratorError(f"TLS auth key not found: {settings.openvpn_ta_key_path}")
    return ta_path.read_text()


def generate_ovpn_config(
    certificate_pem: str,
    private_key_pem: str,
    ca_certificate_pem: str,
    expires_at: str,
    server: str | None = None,
    port: int | None = None,
    proto: str | None = None,
    ta_key: str | None = None,
) -> str:
    """Generate OpenVPN client configuration.

    Args:
        certificate_pem: Client certificate in PEM format.
        private_key_pem: Client private key in PEM format.
        ca_certificate_pem: CA certificate in PEM format.
        expires_at: Certificate expiration timestamp (ISO format).
        server: VPN server hostname (default from settings).
        port: VPN server port (default from settings).
        proto: VPN protocol (default from settings).
        ta_key: TLS auth key content (default from file).

    Returns:
        Complete OpenVPN configuration as string.

    Raises:
        OVPNGeneratorError: If configuration cannot be generated.
    """
    server = server or settings.openvpn_server
    port = port or settings.openvpn_port
    proto = proto or settings.openvpn_proto

    # Load TLS auth key if not provided
    if ta_key is None:
        ta_key = load_ta_key()

    # Strip any trailing newlines from certificates to avoid double newlines
    certificate_pem = certificate_pem.strip()
    private_key_pem = private_key_pem.strip()
    ca_certificate_pem = ca_certificate_pem.strip()
    ta_key = ta_key.strip()

    config = OVPN_TEMPLATE.format(
        server=server,
        port=port,
        proto=proto,
        expires_at=expires_at,
        ca_certificate=ca_certificate_pem,
        certificate=certificate_pem,
        private_key=private_key_pem,
        ta_key=ta_key,
    )

    logger.debug("Generated OVPN config for server %s:%d/%s", server, port, proto)

    return config
